toolu_01JyBFyADswhMrFYaCTpisUW.raw_arguments:
{"cmd":"cd /app; rm -rf /tmp/v; mkdir /tmp/v; 
mk(){ n=$1; shift; mkdir /tmp/v/$n; cp -r shelfmark /tmp/v/$n/; (cd /tmp/v/$n/shelfmark; "$@"); }
mk base true
mk utm sed -i '19s/.*/        if name in cfg.ignore_params or name.startswith("utm_"):/' keys.py
mk loc sed -i '69s/rng/loc/' locale.py
mk ttl sed -i '77s/int(value)/int(value) * 1000/' config.py
mk purge sed -i '26s/|{ident}"/|{ident}|"/' cache.py
for n in base utm loc ttl purge; do echo == $n; python3 tools/replay.py --pkg /tmp/v/$n --since 2027-05-03T11:00:05Z --diff > /tmp/v/$n.out; tail -1 /tmp/v/$n.out; done
for n in utm loc ttl purge; do echo == $n; grep 'logged=miss replay=hit' /tmp/v/$n.out | awk '{print $1}' | sort > /tmp/v/$n.ids; wc -l < /tmp/v/$n.ids; head -1 /tmp/v/$n.ids; done"}

